// The form schemas generated by publiccode-json-schema, one per version of
// the standard: which fields exist in a version and which are deprecated.
import { LATEST_VERSION } from "../contents/publiccode";
import v020 from "../../vendor/publiccode-schema/data/form-schema/form-schema-v0.2.0.json";
import v030 from "../../vendor/publiccode-schema/data/form-schema/form-schema-v0.3.0.json";
import v040 from "../../vendor/publiccode-schema/data/form-schema/form-schema-v0.4.0.json";
import v050 from "../../vendor/publiccode-schema/data/form-schema/form-schema-v0.5.0.json";
import v070 from "../../vendor/publiccode-schema/data/form-schema/form-schema-v0.7.0.json";
import v080 from "../../vendor/publiccode-schema/data/form-schema/form-schema-v0.8.0.json";
import {
  type FormField,
  type FormSchema,
  type SchemaVersion,
  schemaVersionFor,
} from "../../vendor/publiccode-schema/src";

const SCHEMAS = {
  "0.2.0": v020,
  "0.3.0": v030,
  "0.4.0": v040,
  "0.5.0": v050,
  "0.7.0": v070,
  "0.8.0": v080,
} as unknown as Record<SchemaVersion, FormSchema>;

const indexes = new Map<SchemaVersion, Map<string, FormField>>();

const fieldsOf = (version?: string) => {
  const v = schemaVersionFor(version || LATEST_VERSION);
  let index = indexes.get(v);
  if (!index) {
    index = new Map(SCHEMAS[v].fields.map((f) => [f.path, f]));
    indexes.set(v, index);
  }

  return index;
};

export const formSchemaFor = (version?: string): FormSchema =>
  SCHEMAS[schemaVersionFor(version || LATEST_VERSION)];

// Editor field names use the lowercase country section (it.riuso.codiceIPA)
// and no language (genericName): paths in the form schema are
// IT.riuso.codiceIPA and description.*.genericName.
export const toSchemaPath = (fieldName: string) =>
  fieldName.replace(/^it\./, "IT.");

export const formField = (version: string | undefined, path: string) =>
  fieldsOf(version).get(toSchemaPath(path));

// Whether the key exists in that version of the standard.
export const hasField = (version: string | undefined, path: string) =>
  fieldsOf(version).has(toSchemaPath(path));

// Whether the key is deprecated in that version of the standard.
export const isDeprecated = (version: string | undefined, path: string) =>
  Boolean(formField(version, path)?.deprecated);
